{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE gift_card_summary AS ( WITH gift_card_credit AS ( SELECT wt.points_batch_id, TO_VARCHAR(wt.shopify_user_id) AS received_by, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP(wt.created_at)) AS credited_on, TRY_TO_NUMBER(wt.amount) AS amount_credited, TRY_TO_NUMBER(wt.shopify_order_id) AS issued_order_id FROM s3_bucket_wallet_transaction_db wt WHERE wt.type = \'GIFT_CARD_CREDIT\' AND wt.points_batch_id IS NOT NULL ), issued_order_details AS ( SELECT order_id, order_name as issued_order_name, customer_id AS issued_by, MAX(order_timestamp) AS issued_on, SUM(gross_sales) AS issued_gross_sales, SUM(discount) AS issued_discount FROM fact_items_snitch WHERE tags = \'Gift_Card_Purchase\' GROUP BY order_id, customer_id, order_name ), gift_card_debit AS ( SELECT wt.points_batch_id, TO_VARCHAR(wt.shopify_user_id) AS redeemed_by, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TRY_TO_TIMESTAMP(wt.created_at)) AS redeemed_on, ABS(TRY_TO_NUMBER(wt.amount)) AS amount_redeemed, TRIM(SPLIT_PART(wt.shopify_order_number, \'.\', 1)) AS redeemed_order_name FROM s3_bucket_wallet_transaction_db wt WHERE wt.type = \'GIFT_CARD_DEBIT\' AND wt.reason IN (\'Purchase : Online\', \'Purchase : Store\') AND wt.points_batch_id IS NOT NULL ), gift_card_redemption_summary AS ( SELECT points_batch_id, SUM(amount_redeemed) AS total_redeemed FROM gift_card_debit GROUP BY points_batch_id ), redeemed_order_details AS ( SELECT order_name, MAX(order_timestamp) AS redeemed_order_ts, SUM(gross_sales) AS redeemed_gross_sales, SUM(discount) AS redeemed_discount, MAX(LOWER(order_status)) AS status FROM fact_items_snitch WHERE gross_sales > 0 AND LOWER(order_status) NOT LIKE \'%cancel%\' AND LOWER(tags) NOT LIKE \'%creator%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code,\'n\')) NOT LIKE \'%influ%\' GROUP BY order_name ), user_orders_summary AS ( SELECT customer_id, MIN(order_timestamp) AS first_order_date FROM fact_items_snitch GROUP BY customer_id ), snitchx_membership AS ( SELECT DISTINCT TRIM(shopify_user_id) AS shopify_user_id, CONVERT_TIMEZONE( \'UTC\',\'Asia/Kolkata\', CASE WHEN membership_enrolled_date LIKE \'__-__-____ __:__\' THEN TO_TIMESTAMP(CONCAT(TRIM(membership_enrolled_date), \':00\'), \'DD-MM-YYYY HH24:MI:SS\') ELSE TRY_TO_TIMESTAMP(TRIM(membership_enrolled_date)) END ) AS snitchx_enrolled_at FROM snitch_db.maplemonk.s3_bucket_wallet_db WHERE membership_plan = \'SILVER\' ) SELECT c.points_batch_id, od.issued_by, od.issued_order_name, od.issued_on, od.issued_gross_sales, od.issued_discount, c.received_by, c.credited_on, c.amount_credited, d.redeemed_by, d.redeemed_on, d.amount_redeemed, rd.order_name, rd.redeemed_order_ts, rd.redeemed_gross_sales, rd.redeemed_discount, CASE WHEN grs.total_redeemed IS NULL THEN \'Unredeemed\' WHEN grs.total_redeemed = c.amount_credited THEN \'Fully Redeemed\' WHEN grs.total_redeemed < c.amount_credited THEN \'Partially Redeemed\' ELSE \'Check\' END AS redemption_status, CASE WHEN rd.order_name IS NULL THEN NULL ELSE DATEDIFF(DAY, od.issued_on, d.redeemed_on) END AS tat_purchase_to_redeem, CASE WHEN c.credited_on IS NULL THEN NULL ELSE DATEDIFF(DAY, od.issued_on, c.credited_on) END AS tat_purchase_to_credit, CASE WHEN d.redeemed_on IS NULL THEN NULL ELSE DATEDIFF(DAY, c.credited_on, rd.redeemed_order_ts) END AS tat_credit_to_redeem, CASE WHEN credited_on IS NOT NULL THEN NULL WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 8 THEN \'0–7 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 16 THEN \'8–15 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 30 THEN \'16–30 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 60 THEN \'31–60 days\' ELSE \'> 60 days\' END AS not_credited_ageing_bucket, CASE WHEN grs.total_redeemed >= c.amount_credited THEN NULL WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 8 THEN \'0–7 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) < 16 THEN \'8–15 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 30 THEN \'16–30 days\' WHEN DATEDIFF(DAY, od.issued_on, CURRENT_DATE) <= 60 THEN \'31–60 days\' ELSE \'> 60 days\' END AS unredeemed_ageing_bucket, CASE WHEN rd.order_name IS NULL THEN \'Not Redeemed\' WHEN od.issued_by = d.redeemed_by THEN \'Yes\' ELSE \'No\' END AS redeemed_by_same_user, CASE WHEN sm_issuer.shopify_user_id IS NOT NULL AND od.issued_on >= sm_issuer.snitchx_enrolled_at THEN \'X\' WHEN uos_issuer.first_order_date IS NULL THEN \'New\' WHEN uos_issuer.first_order_date >= od.issued_on THEN \'New\' ELSE \'Repeat\' END AS issuer_type, CASE WHEN rd.order_name IS NULL THEN NULL WHEN sm_redeemer.shopify_user_id IS NOT NULL AND d.redeemed_on >= sm_redeemer.snitchx_enrolled_at THEN \'X\' WHEN uos_redeemer.first_order_date IS NULL THEN \'New\' WHEN uos_redeemer.first_order_date >= d.redeemed_on THEN \'New\' ELSE \'Repeat\' END AS redeemer_type FROM issued_order_details od LEFT JOIN gift_card_credit c ON od.order_id = c.issued_order_id LEFT JOIN gift_card_debit d ON c.points_batch_id = d.points_batch_id LEFT JOIN redeemed_order_details rd ON d.redeemed_order_name = rd.order_name LEFT JOIN user_orders_summary uos_issuer ON od.issued_by = uos_issuer.customer_id LEFT JOIN gift_card_redemption_summary grs ON c.points_batch_id = grs.points_batch_id LEFT JOIN user_orders_summary uos_redeemer ON d.redeemed_by = uos_redeemer.customer_id LEFT JOIN snitchx_membership sm_issuer ON od.issued_by = sm_issuer.shopify_user_id LEFT JOIN snitchx_membership sm_redeemer ON d.redeemed_by = sm_redeemer.shopify_user_id WHERE ISSUED_ON > \'2025-06-10\' ORDER BY ISSUED_ON DESC); CREATE OR REPLACE TABLE gift_card_share_total AS( SELECT order_timestamp::DATE as order_date, sum(amount_redeemed) gift_card_amount, sum(net_sales) as total_revenue from fact_items_snitch f left join gift_card_summary g on f.ORDER_NAME = g.issued_order_name WHERE order_timestamp >= \'2025-06-11\' GROUP BY order_timestamp::DATE ORDER BY order_timestamp::DATE DESC);",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            